  append Rooms { title: r.patient, start: r.session_at, duration: 45 minutes }
  let m = draft sms to r.mobile: "Hi {r.patient default 'there'}, your session with {r.therapist} is confirmed at {time_of(r.session_at)}."
  let ok = request approval of m from owner timeout 6 hours else skip
  send ok
  update r set status = "confirmed"
}
