procedure CoffeeOrder {
  about "Place a weekly standing order for beans"
  policy CoffeePolicy
  sheet Beans "Beans" { blend: Text, bags: Number, reorder_at: Number, order_bags: Number, roaster: Text, price_per_bag: Money }
  trigger every monday at 7

  let house_blend = filter Beans where blend == "house" and bags >= order_bags
  if empty(house_blend) {
    notify owner "House blend not available."
    stop "out of stock"
  }
  let total_cost = sum price_per_bag * bags of house_blend
  if total_cost > $500.00 {
    notify owner "Total order cost exceeds $500. Please adjust."
    stop "order limit exceeded"
  }
  order "house" from Bean Brothers bags order_bags, ask owner first timeout 4 hours else skip
  notify owner "Weekly standing order placed for 40 bags of the house blend from Bean Brothers."
}
```

