procedure HardwareReturns {
  about "Handle hardware returns within limits"
  policy HardwarePolicy
  sheet Returns "Returns" { return_no: Text, customer: Text, phone: Phone, amount: Money, bought: Date, opened: Bool, status: Text }
  trigger when new row r in Returns

  if r.opened {
    notify owner "Return {r.return_no} has already been opened."
    stop "return already opened"
  }
  if days_between(r.bought, today()) > 30 {
    notify owner "Return {r.return_no} is older than 30 days."
    stop "outside return window"
  }
  if r.amount > $100.00 {
    notify owner "Return {r.return_no} is {r.amount}, over $100. Please review."
    stop "over refund limit"
  }
  refund r.amount for r.return_no reason "hardware return", ask owner first timeout 6 hours else stop "refund not approved"
  update r set status = "refunded"
  let m = draft sms to r.phone: "Hi {r.customer default 'there'}, your hardware return of {r.amount} has been issued."
  let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
  send ok
}
```

