procedure ClientWelcome {
  about "Send welcome emails and track document receipt"
  policy TaxPolicy
  sheet Clients "Clients" { client: Text, email: Email, docs_received: Bool, deadline: Date, fee: Money, status: Text, ssn_last4: Text private }
  trigger when new row r in Clients

  let m = draft email to r.email subject "Welcome to our service!" body "Please see the attached document checklist for your files. We will send another reminder if your documents are not received by {deadline}."
  let ok = request approval of m from owner timeout 6 hours else skip
  send ok
  update r set status = "welcomed"
  wait 7 days
  if not r.docs_received {
    let m = draft email to r.email subject "Reminder: Missing documents" body "Your documents have not been received by {deadline}. Please provide them as soon as possible."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
  }
}

