procedure OptomExamCancellation {
  about "Notify waitlist members of available spots after an exam cancellation"
  policy OptomPolicy
  sheet Cancellations "Cancellations" { event_id: Text, slot_text: Text }
  sheet Waitlist "Waitlist" { patient: Text, phone: Phone, joined: Date, status: Text }
  calendar Exams "Exams"

  let cancel = fetch Cancellations
  let exam = filter cancel where event_id == cancel.event_id
  let earliest = min(waitlist.joined) where waitlist.status == "waiting"
  if earliest != null {
    let m = draft sms to earliest.phone: "Hi {earliest.patient default 'there'}, a spot has opened for your exam on {exam.slot_text}."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
    update waitlist set status = "offered" where waitlist.patient == earliest.patient
  } else {
    stop "no waitlist members available"
  }
}
