procedure IcePartyCancellation {
  about "Handle party cancellations within limits"
  policy IcePolicy
  sheet PartyCancellations "PartyCancellations" { ref: Text, host: Text, phone: Phone, deposit: Money, party_on: Date }
  trigger when new row r in PartyCancellations

  if days_between(r.party_on, today()) < 3 {
    notify owner "Party cancellation {r.ref} is less than 3 days away."
    stop "party too soon"
  }
  if r.deposit > $100.00 {
    notify owner "Deposit for party cancellation {r.ref} is {r.deposit}. Please review."
    stop "deposit too high"
  }
  if r.deposit <= $40.00 {
    refund r.deposit for r.ref reason "party cancellation", ask owner first timeout 6 hours else skip
    update r set status = "canceled"
    let m = draft sms to r.host: "Hi {r.host}, your deposit of {r.deposit} is returning."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
  } else {
    refund r.deposit for r.ref reason "party cancellation", ask owner first timeout 6 hours else skip
    update r set status = "pending"
    let m = draft sms to r.host: "Hi {r.host}, your deposit of {r.deposit} is pending refund."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
  }
}
```

