procedure VenueBookingApproval {
  about "Approve new bookings"
  policy VenuePolicy
  sheet Bookings "Bookings" { client: Text, email: Email, event_date: Date, hall: Text, balance: Money, status: Text, contract_notes: Text private }
  sheet Halls "Halls"
  trigger when new row r in Bookings

  if r.hall == "" {
    notify owner "No hall selected for booking {r.client}."
    stop "missing hall selection"
  }
  let h = fetch Halls where name == r.hall
  if h == null {
    notify owner "Hall {r.hall} does not exist."
    stop "invalid hall"
  }
  let d = date_of(r.event_date) + 8 hours
  append Halls { name: r.hall, start_time: d, end_time: d + 8 hours, title: r.client }
  let m = draft email to r.email subject "Your booking for {r.client} has been confirmed." body "Thank you for choosing us. We will meet you at {d} in the {r.hall}."
  let ok = request approval of m from owner timeout 6 hours else skip
  send ok
  update r set status = "confirmed"
}
