procedure MoveRefunds {
  about "Handle move cancellations within limits"
  policy MovePolicy
  sheet MoveCancellations "MoveCancellations" { job: Text, customer: Text, phone: Phone, deposit: Money, move_date: Date }
  trigger when new row r in MoveCancellations

  if days_between(r.move_date, today()) > 7 {
    notify owner "Move cancellation {r.job} is more than 7 days away."
    stop "move not cancelled within 7 days"
  }
  if r.deposit > $200.00 {
    notify owner "Deposit for move {r.job} is {r.deposit}. Please review."
    stop "deposit over $200"
