  refund r.deposit for r.job reason "move cancellation", ask owner first timeout 6 hours else stop "refund not approved"
  let m = draft sms to r.phone: "Hi {r.customer default 'there'}, your deposit of {r.deposit} has been refunded."
  let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
  send ok
}
