procedure MoveSummary {
  about "Summarize upcoming booked moves"
  policy MovePolicy
  sheet Moves "Moves" { customer: Text, phone: Phone, move_date: Date, crew: Text, deposit: Money, estimate: Money, status: Text, access_notes: Text private }
  trigger every monday at 07:00

  let all = fetch Moves
  let booked = filter all where status == "booked" and date_of(move_date) >= today()
  let total_estimates = sum estimate of booked
  let avg_estimate = avg estimate of booked
  let summary = format "Total estimated moves: ${total_estimates}\nAverage estimate: ${avg_estimate}"
  notify owner "Move summary: ${summary}"
}

