procedure TicketAcknowledgements {
  about "Notify customers of new tickets and wait for response"
  policy RepairPolicy
  sheet Tickets "Tickets" { ticket: Text, customer: Text, email: Email, opened: Date, device: Text, status: Text, password: Text private }
  trigger when new row r in Tickets

  let m = draft email to r.email subject "Ticket #{r.ticket}" body "Thank you for opening a ticket. Your ticket number is {r.ticket}. We will get back to you as soon as possible."
  let ok = request approval of m from owner timeout 6 hours else skip
  send ok
  wait 3 days
  let t = fetch Tickets where ticket == r.ticket and status == "new"
  if count of t == 0 {
    notify owner "Ticket #{r.ticket} has not been touched after 3 days."
    stop "ticket not responded to"
  }
}

