  about "Send welcome note and track client status"
  policy PhotostudioPolicy
  sheet Shoots "Shoots" { client: Text, email: Email, shoot_on: Date, status: Text, deposit: Money, venue_notes: Text private }
  trigger when new row r in Shoots

  let m = draft email to r.email subject "Welcome to our photo studio!" body "Thank you for choosing us. We look forward to seeing you soon!"
  let ok = request approval of m from owner timeout 2 hours else skip
  send ok
  update r set status = "contacted"

  wait 2 days
  if r.status == "shot" or r.status == "cancelled" {
    stop "client already shot/cancelled"
  } else {
    let m = draft sms to r.email subject "Check-in reminder" body "Your photo session is scheduled for {shoot_on}. Please arrive early."
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
  }
}
```

