procedure FloristOrderCheck {
  about "Check stock levels and place orders as needed"
  policy FloristStockPolicy
  sheet Flowers "Flowers" { flower: Text, stems: Number, minimum: Number, reorder_qty: Number, grower: Text, unit_cost: Money }
  trigger every day at 11:00

  let all = fetch Flowers
  for each f in all where f.stems < f.minimum {
    let order_amount = f.reorder_qty * f.unit_cost
    if order_amount > $100.00 {
      notify owner "Cannot order more than $100 for {f.flower}."
      stop "order limit exceeded"
    }
    order f.flower { quantity: f.reorder_qty, at: today() }
  }
}
```

