procedure FloristRefunds {
  about "Handle refund requests within limits"
  policy FloristRefundPolicy
  sheet RefundRequests "RefundRequests" { request_id: Text, customer: Text, email: Email, amount: Money, purchased: Date, status: Text }
  trigger when new row r in RefundRequests

  if days_between(r.purchased, today()) > 60 {
    notify owner "Refund request {r.request_id} is older than 60 days."
    stop "outside refund window"
  }
  if r.amount > $40.00 {
    notify owner "Refund request {r.request_id} is {r.amount}, over $40. Please review."
    stop "over refund limit"
  }
  if r.amount <= $20.00 {
    refund r.amount for r.request_id reason "refund request", ask owner first timeout 6 hours else skip
    update r set status = "refunded"
    let m = draft email to r.email subject "Your refund of {r.amount} has been issued." body "Thank you for choosing us!"
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
  } else {
    notify owner "Refund request {r.request_id} is over $20, please review."
    stop "over refund limit"
  }
}
```

