  policy PlumbingPolicy
  sheet Calls "Calls" { customer: Text, phone: Phone, visit_at: DateTime, status: Text, invoice: Money, alarm_code: Text private }
  trigger every wednesday at 16:00

  let all = fetch Calls
  let targets = filter all where status == "no-access" and days_between(visit_at, today()) <= 7
  let n = summarize count of targets
  if n == 0 {
    notify owner "No customers marked 'no-access' in the last 7 days."
    stop "no customers to remind"
  }
  append Outreach { day: today(), campaign: "new time", targeted: n }
  let msgs = draft each r in targets up to 20 sms to r.phone: "Hi {r.customer default 'there'}, we noticed you had no access to our plumbing service. We would like to offer you a new time to schedule your visit. Please let us know if you are available."
  let ok = request batch approval of msgs from owner timeout 1 minute else stop "batch not approved"
  send ok
}
```

