procedure VetWelcomeAndCheckIns {
  about "Send welcome notes and check-ins to new pet owners"
  policy VetPolicy
  sheet Pets "Pets" { owner: Text, phone: Phone, vaccine_due: Date, status: Text, balance: Money, medical_notes: Text private }
  trigger when new row r in Pets

  let m = draft sms to r.phone: "Hi {r.owner default 'there'}, welcome to our veterinary clinic! We hope you have a great day."
  let ok = request approval of m from owner timeout 6 hours else skip
  send ok
  update r set status = "contacted"

  wait 2 days
  if r.status == "due" or r.status == "inactive" {
    stop "pet is due or inactive"
  } else {
    let m = draft sms to r.phone: "Hi {r.owner default 'there'}, we hope you had a good day at the clinic. Here's your check-in."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
  }
}
